// Data Validation — reject malformed readings, clamp out-of-range values,
// drop stale or duplicate messages.
const p = msg.payload;
const errors = [];

if (!p || typeof p !== 'object') {
    node.warn('Invalid payload (not JSON object)');
    return [null, { payload: { reason: 'not-an-object', raw: msg.payload, topic: msg.topic } }];
}
if (typeof p.intersectionId !== 'string' || !/^INT-\d{3}$/.test(p.intersectionId)) errors.push('intersectionId');
if (!Array.isArray(p.approaches) || p.approaches.length === 0) errors.push('approaches');
const ts = Date.parse(p.timestamp);
if (isNaN(ts)) errors.push('timestamp');
else if (Math.abs(Date.now() - ts) > 5 * 60 * 1000) errors.push('timestamp-stale');

if (errors.length) {
    return [null, { payload: { reason: 'invalid-fields', fields: errors, intersectionId: p.intersectionId, topic: msg.topic } }];
}

// duplicate / out-of-order protection per sensor
const seqKey = 'seq_' + p.intersectionId;
const lastSeq = context.get(seqKey) || 0;
if (typeof p.seq === 'number' && p.seq <= lastSeq && p.seq > 5) {
    return [null, { payload: { reason: 'duplicate-or-out-of-order', seq: p.seq, lastSeq, intersectionId: p.intersectionId } }];
}
if (typeof p.seq === 'number') context.set(seqKey, p.seq);

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, Number(v) || 0));
const VALID_APPROACHES = ['N', 'S', 'E', 'W'];
let clamped = 0;
p.approaches = p.approaches
    .filter(a => a && VALID_APPROACHES.includes(a.approach))
    .map(a => {
        const out = {
            approach: a.approach,
            vehicleCount: Math.round(clamp(a.vehicleCount, 0, 5000)),
            avgSpeed: clamp(a.avgSpeed, 0, 200),
            occupancy: clamp(a.occupancy, 0, 100),
            queueLength: Math.round(clamp(a.queueLength, 0, 1000)),
            incident: !!a.incident
        };
        if (out.vehicleCount !== a.vehicleCount || out.avgSpeed !== a.avgSpeed || out.occupancy !== a.occupancy) clamped++;
        return out;
    });

if (p.approaches.length === 0) {
    return [null, { payload: { reason: 'no-valid-approaches', intersectionId: p.intersectionId } }];
}

p.lanes = clamp(p.lanes || 2, 1, 6);
p.freeFlowSpeed = clamp(p.freeFlowSpeed || 50, 20, 130);
p.intervalSec = clamp(p.intervalSec || 5, 1, 3600);
p.vehicles = Array.isArray(p.vehicles) ? p.vehicles : [];
p.emergency = p.emergency && p.emergency.detected ? p.emergency : { detected: false };
p.validation = { ok: true, clampedFields: clamped, receivedAt: new Date().toISOString() };

msg.payload = p;
return [msg, null];

// Data Processing + Congestion Detection
//   flow (veh/h)      = count * 3600 / interval
//   density (veh/km/lane) = flow / speed / lanes   (fundamental diagram q = k * v)
//   congestion score  = 0.45*occupancy + 0.35*speed loss + 0.20*queue pressure  (0..1)
const p = msg.payload;
const LEVELS = [
    { level: 'free', max: 0.30 },
    { level: 'moderate', max: 0.50 },
    { level: 'heavy', max: 0.70 },
    { level: 'severe', max: 1.01 }
];
const levelOf = s => LEVELS.find(l => s < l.max).level;
const round = (v, d = 1) => Math.round(v * 10 ** d) / 10 ** d;
const queueCapacity = p.lanes * 120 / 6.5; // vehicles that fit in the detection zone

let totalCount = 0, totalFlow = 0, speedWeighted = 0, occSum = 0, queueSum = 0, maxScore = 0;
p.approaches = p.approaches.map(a => {
    const flow = a.vehicleCount * 3600 / p.intervalSec;
    const speed = Math.max(a.avgSpeed, 1);
    const density = flow / speed / p.lanes;
    const speedLoss = Math.max(0, 1 - a.avgSpeed / p.freeFlowSpeed);
    const queuePressure = Math.min(1, a.queueLength / queueCapacity);
    let score = 0.45 * (a.occupancy / 100) + 0.35 * speedLoss + 0.20 * queuePressure;
    if (a.incident) score = Math.min(1, score + 0.1);
    score = round(Math.min(1, score), 3);

    totalCount += a.vehicleCount;
    totalFlow += flow;
    speedWeighted += a.avgSpeed * Math.max(a.vehicleCount, 1);
    occSum += a.occupancy;
    queueSum += a.queueLength;
    maxScore = Math.max(maxScore, score);

    return Object.assign({}, a, {
        flowVph: Math.round(flow),
        density: round(density),
        congestionScore: score,
        congestionLevel: levelOf(score)
    });
});

const weightSum = p.approaches.reduce((s, a) => s + Math.max(a.vehicleCount, 1), 0);
const avgScore = p.approaches.reduce((s, a) => s + a.congestionScore, 0) / p.approaches.length;
// intersection score leans towards the worst approach
const interScore = round(0.6 * maxScore + 0.4 * avgScore, 3);

p.summary = {
    vehicleCount: totalCount,
    flowVph: Math.round(totalFlow),
    avgSpeed: round(speedWeighted / weightSum),
    avgOccupancy: round(occSum / p.approaches.length),
    totalQueue: queueSum,
    density: round(p.approaches.reduce((s, a) => s + a.density, 0) / p.approaches.length),
    congestionScore: interScore,
    congestionLevel: levelOf(interScore),
    incidents: p.approaches.filter(a => a.incident).map(a => a.approach)
};

// Congestion alerting with hysteresis: alert when entering heavy/severe,
// clear when back to free/moderate. Avoids an alert every 5 seconds.
const key = 'level_' + p.intersectionId;
const prev = context.get(key) || 'free';
const curr = p.summary.congestionLevel;
const rank = { free: 0, moderate: 1, heavy: 2, severe: 3 };
p.alerts = [];
if (rank[curr] >= 2 && rank[curr] > rank[prev]) {
    p.alerts.push({
        type: 'congestion',
        severity: curr === 'severe' ? 'critical' : 'warning',
        message: `${curr === 'severe' ? 'Severe' : 'Heavy'} congestion at ${p.intersectionId} (score ${interScore}, avg speed ${p.summary.avgSpeed} km/h)`
    });
} else if (rank[curr] <= 1 && rank[prev] >= 2) {
    p.alerts.push({ type: 'congestion_cleared', severity: 'info', message: `Congestion cleared at ${p.intersectionId}` });
}
context.set(key, curr);

// incident alert (once per incident start)
const incKey = 'inc_' + p.intersectionId;
const prevInc = context.get(incKey) || [];
p.summary.incidents.filter(a => !prevInc.includes(a)).forEach(a => {
    p.alerts.push({ type: 'incident', severity: 'warning', message: `Possible incident on approach ${a} at ${p.intersectionId} (capacity drop detected)` });
});
context.set(incKey, p.summary.incidents);

msg.payload = p;
return msg;

// Signal Optimization (Webster's method) + manual override handling.
// Two-phase control: NS phase (approaches N,S) and EW phase (approaches E,W).
//   y_i = critical flow / saturation flow   (critical = busier approach in the phase, incl. queue)
//   C0  = (1.5 L + 5) / (1 - Y),  L = lost time per cycle, Y = sum(y_i)
//   g_i = (C0 - L) * y_i / Y
const p = msg.payload;
const SAT_FLOW = 1800;          // veh/h/lane
const LOST_PER_PHASE = 4;       // s (start-up + clearance)
const YELLOW = 3, ALL_RED = 2;
const MIN_GREEN = 10, MIN_CYCLE = 40, MAX_CYCLE = 150;
const round = v => Math.round(v);

const byApproach = {};
p.approaches.forEach(a => { byApproach[a.approach] = a; });
// demand = measured flow + queued vehicles that need to clear within ~ one cycle (90 s)
const demand = a => a ? a.flowVph + a.queueLength * 3600 / 90 : 0;
const nsCrit = Math.max(demand(byApproach.N), demand(byApproach.S));
const ewCrit = Math.max(demand(byApproach.E), demand(byApproach.W));
const cap = SAT_FLOW * p.lanes;
let yNS = Math.max(0.05, nsCrit / cap);
let yEW = Math.max(0.05, ewCrit / cap);
let Y = yNS + yEW;
const L = 2 * LOST_PER_PHASE;
if (Y > 0.9) { yNS = yNS / Y * 0.9; yEW = yEW / Y * 0.9; Y = 0.9; } // oversaturated: cap

let cycle = Math.min(MAX_CYCLE, Math.max(MIN_CYCLE, (1.5 * L + 5) / (1 - Y)));
let effGreen = cycle - L;
let nsGreen = Math.max(MIN_GREEN, effGreen * yNS / Y);
let ewGreen = Math.max(MIN_GREEN, effGreen * yEW / Y);
cycle = nsGreen + ewGreen + L;

// smooth changes so the plan doesn't jump every 5 s (exponential smoothing)
const key = 'plan_' + p.intersectionId;
const prev = context.get(key);
if (prev) {
    const a = 0.3;
    nsGreen = prev.nsGreen + a * (nsGreen - prev.nsGreen);
    ewGreen = prev.ewGreen + a * (ewGreen - prev.ewGreen);
    cycle = nsGreen + ewGreen + L;
}

let plan = {
    intersectionId: p.intersectionId,
    mode: 'adaptive',
    cycleLength: round(cycle),
    nsGreen: round(nsGreen),
    ewGreen: round(ewGreen),
    yellow: YELLOW,
    allRed: ALL_RED,
    preemptApproach: null,
    reason: 'webster',
    flowRatio: { ns: Math.round(yNS * 1000) / 1000, ew: Math.round(yEW * 1000) / 1000 }
};
context.set(key, { nsGreen, ewGreen });

// manual override (set from the dashboard via traffic/control/<id>)
const overrides = flow.get('overrides') || {};
const ov = overrides[p.intersectionId];
if (ov && ov.mode === 'manual') {
    plan = Object.assign(plan, {
        mode: 'manual',
        nsGreen: ov.nsGreen,
        ewGreen: ov.ewGreen,
        cycleLength: ov.nsGreen + ov.ewGreen + L,
        reason: 'manual-override'
    });
}

// detect significant plan change -> persist in signal history
const lastSent = context.get('sent_' + p.intersectionId);
plan.changed = !lastSent || lastSent.mode !== plan.mode ||
    Math.abs(lastSent.nsGreen - plan.nsGreen) >= 3 || Math.abs(lastSent.ewGreen - plan.ewGreen) >= 3;
if (plan.changed) context.set('sent_' + p.intersectionId, { mode: plan.mode, nsGreen: plan.nsGreen, ewGreen: plan.ewGreen });

p.signal = plan;
msg.payload = p;
return msg;

// Emergency Detection — pre-empt the signal to give green to the emergency
// vehicle's approach, raise a critical alert once per vehicle, and restore
// normal operation when the vehicle has passed.
const p = msg.payload;
const e = p.emergency;
const key = 'ev_' + p.intersectionId;
const active = context.get(key);

if (e && e.detected) {
    const phase = (e.approach === 'N' || e.approach === 'S') ? 'NS' : 'EW';
    p.signal = Object.assign({}, p.signal, {
        mode: 'emergency',
        preemptApproach: e.approach,
        nsGreen: phase === 'NS' ? 60 : 0,
        ewGreen: phase === 'EW' ? 60 : 0,
        cycleLength: 60 + 8,
        reason: `emergency-preemption:${e.type}`,
        changed: !active || active.vehicleId !== e.vehicleId
    });
    p.priority = 'high';
    if (!active || active.vehicleId !== e.vehicleId) {
        p.alerts = (p.alerts || []).concat([{
            type: 'emergency',
            severity: 'critical',
            message: `${e.type.replace('_', ' ')} ${e.vehicleId} approaching ${p.intersectionId} from ${e.approach} — signal pre-empted (${phase} green)`
        }]);
        context.set(key, { vehicleId: e.vehicleId, since: Date.now() });
    }
} else if (active) {
    p.alerts = (p.alerts || []).concat([{
        type: 'emergency_cleared',
        severity: 'info',
        message: `Emergency vehicle ${active.vehicleId} cleared ${p.intersectionId} — resuming ${p.signal.mode} control`
    }]);
    p.signal.changed = true;
    context.set(key, null);
}

// Output 1: full processed record -> backend
// Output 2: signal plan -> MQTT traffic/signals/<id> (retained)
const signalMsg = { topic: 'traffic/signals/' + p.intersectionId, payload: p.signal, retain: true, qos: 1 };
msg.payload = p;
return [msg, signalMsg];

// Publish results on MQTT
//   output 1: processed record -> traffic/processed/<intersectionId>
//   output 2: one message per alert -> traffic/alerts/<intersectionId>
const p = msg.payload;
const id = p.intersectionId;

const processed = {
    topic: 'traffic/processed/' + id,
    payload: p,
    qos: 0,
    retain: true          // latest state per intersection is always available
};

const alerts = (p.alerts || []).map(a => ({
    topic: 'traffic/alerts/' + id,
    payload: Object.assign({ intersectionId: id, timestamp: p.timestamp }, a),
    qos: 1,
    retain: false
}));

const stats = flow.get('stats') || { processed: 0, alerts: 0 };
stats.processed++;
stats.alerts += alerts.length;
flow.set('stats', stats);
node.status({ fill: 'green', shape: 'dot', text: `${stats.processed} processed · ${stats.alerts} alerts` });

return [processed, alerts];

// Backend Routing — forward the processed record to the Node.js backend.
const base = env.get('BACKEND_URL') || 'http://backend:4000';
msg.url = base + '/api/ingest';
msg.method = 'POST';
msg.headers = {
    'content-type': 'application/json',
    'x-ingest-token': env.get('INGEST_TOKEN') || 'dev-ingest-token'
};
const stats = flow.get('stats') || { processed: 0 };
stats.processed++;
flow.set('stats', stats);
node.status({ fill: 'green', shape: 'dot', text: `forwarded ${stats.processed}` });
return msg;

if (msg.statusCode >= 300 || msg.statusCode === undefined) {
  node.status({ fill: 'red', shape: 'ring', text: 'backend ' + (msg.statusCode || 'unreachable') });
  node.warn('Backend rejected ingest: ' + (msg.statusCode || 'unreachable') + ' ' + JSON.stringify(msg.payload));
} else {
  node.status({ fill: 'green', shape: 'dot', text: 'backend ok' });
}
return null;

// Manual control commands from the dashboard (published by the backend on
// traffic/control/<intersectionId>). Stored in flow context and applied by the
// Signal Optimization node on the next reading.
const c = msg.payload || {};
const id = (msg.topic || '').split('/').pop();
if (!/^INT-\d{3}$/.test(id)) return null;
const overrides = flow.get('overrides') || {};
if (c.mode === 'manual') {
    const g = v => Math.min(120, Math.max(10, Math.round(Number(v) || 0)));
    overrides[id] = { mode: 'manual', nsGreen: g(c.nsGreen), ewGreen: g(c.ewGreen), at: Date.now() };
} else {
    delete overrides[id];
}
flow.set('overrides', overrides);
node.status({ fill: Object.keys(overrides).length ? 'yellow' : 'green', shape: 'dot', text: `${Object.keys(overrides).length} manual override(s)` });
return null;
